import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";

import { afterEach, describe, expect, it, vi } from "vitest";
import { resolveKirieConfig } from "../config.ts";
import {
  assembleDotnetWebExport,
  checkDotnetWebToolchain,
  type DotnetWebRelease,
  exportDotnetWebPack,
  installDotnetWebToolchain,
  patchDotnetWebExport,
  publishDotnetWeb,
  resolveDotnetWebInstallDir,
  tryExportDotnetWeb,
} from "./dotnet-web.ts";

const payloadFiles = [
  "Godot.NET.Sdk.4.7.2.nupkg",
  "Godot.SourceGenerators.4.7.2.nupkg",
  "GodotSharp.4.7.2.nupkg",
  "GodotSharpEditor.4.7.2.nupkg",
  "web_debug.zip",
  "web_release.zip",
] as const;
const tempDirs: string[] = [];

afterEach(async () => {
  vi.restoreAllMocks();
  await Promise.all(tempDirs.splice(0).map((dir) => fs.rm(dir, { force: true, recursive: true })));
});

describe(".NET Web toolchain", () => {
  it("validates the templates and wasm-tools", async () => {
    const homeDir = await tempDir();
    const release = testRelease();
    const installDir = resolveDotnetWebInstallDir({
      arch: "x64",
      homeDir,
      platform: "linux",
      release,
    });
    await writeToolchain(installDir, release);

    await expect(checkDotnetWebToolchain({
      arch: "x64",
      homeDir,
      platform: "linux",
      release,
      runDotnetWorkloadList: async () => "wasm-tools 10.0.112",
    })).resolves.toMatchObject({
      toolchain: { root: installDir },
      valid: true,
    });

    await expect(checkDotnetWebToolchain({
      arch: "x64",
      homeDir,
      platform: "linux",
      release,
      runDotnetWorkloadList: async () => "",
    })).resolves.toMatchObject({
      message: expect.stringContaining("wasm-tools workload is not installed"),
      valid: false,
    });

    await fs.writeFile(path.join(installDir, "web_release.zip"), "changed");
    await expect(checkDotnetWebToolchain({
      arch: "x64",
      homeDir,
      platform: "linux",
      release,
    })).resolves.toMatchObject({
      message: expect.stringContaining("web_release.zip is missing or invalid"),
      valid: false,
    });
  });

  it("installs the release and wasm-tools without writing project paths", async () => {
    const homeDir = await tempDir();
    const archive = await tempDir();
    const projectDir = await tempDir();
    const release = testRelease();
    await writeToolchain(archive, release);
    const runGodot = vi.fn(async () => {});
    const runDotnet = vi.fn(async () => {});
    const download = vi.fn(async ({ outputPath }: { outputPath: string }) => {
      await fs.writeFile(outputPath, "archive");
    });

    await installDotnetWebToolchain({
      arch: "x64",
      download,
      extractArchive: async (_file, output) => fs.cp(archive, output, { recursive: true }),
      godotArgs: [],
      godotCommand: "godot-mono",
      homeDir,
      platform: "linux",
      projectDir,
      release,
      runDotnet,
      runGodot,
    });

    expect(download).toHaveBeenCalledWith(expect.objectContaining({
      expectedSha256: release.asset.sha256,
      url: release.asset.url,
    }));
    expect(runDotnet).toHaveBeenCalledWith(
      "dotnet",
      ["workload", "install", "wasm-tools"],
      projectDir,
    );
    expect(runGodot).toHaveBeenCalledWith(
      "godot-mono",
      expect.arrayContaining(["--headless", "--script"]),
      projectDir,
    );
    await expect(fs.access(path.join(projectDir, "NuGet.Config"))).rejects.toThrow();
  });
});

describe(".NET Web export", () => {
  it("requires doctor setup and then runs the C# Web export path", async () => {
    const projectDir = await tempDir();
    const homeDir = await tempDir();
    const release = testRelease();
    const outputPath = path.join(projectDir, "dist", "web", "index.html");
    await fs.writeFile(path.join(projectDir, "Example.csproj"), "<Project />");
    await fs.mkdir(path.join(projectDir, "src-web", "dist"), { recursive: true });
    await fs.writeFile(path.join(projectDir, "src-web", "dist", "index.html"), "web");
    const config = resolveKirieConfig(undefined, { cwd: projectDir, mode: "production" });
    const options = {
      arch: "x64" as const,
      build: false,
      config,
      godotCommand: "godot",
      homeDir,
      outputPath,
      platform: "linux" as const,
      preset: "Web",
      release: false,
      toolchainRelease: release,
    };

    await expect(tryExportDotnetWeb(options)).rejects.toThrow("pnpm kirie doctor --fix web");

    await writeToolchain(resolveDotnetWebInstallDir({
      arch: "x64",
      homeDir,
      platform: "linux",
      release,
    }), release);
    const publish = vi.fn(async () => {});
    await expect(tryExportDotnetWeb({
      ...options,
      runAssembly: async ({ outputPath: output }) => {
        await fs.mkdir(path.dirname(output), { recursive: true });
        await fs.writeFile(output.replace(/\.html$/, ".js"), "DOTNET.setup({});;\nafter\n");
      },
      runPack: async ({ outputPath: output }) => fs.writeFile(output, "pack"),
      runPublish: publish,
      runDotnetWorkloadList: async () => "wasm-tools",
    })).resolves.toBe(true);

    expect(publish).toHaveBeenCalledOnce();
    await expect(fs.readFile(path.join(projectDir, "dist", "web", "index.js"), "utf8"))
      .resolves
      .toBe("after\n");
    await expect(
      fs.readFile(path.join(projectDir, "dist", "web", "src-web", "dist", "index.html"), "utf8"),
    ).resolves.toBe("web");
  });

  it("publishes browser-wasm files and writes the runtime manifest", async () => {
    const projectDir = await tempDir();
    const outputDir = path.join(projectDir, "publish");
    const projectFile = path.join(projectDir, "Example.csproj");
    await fs.writeFile(projectFile, "<Project />");
    const runDotnet = vi.fn(async (
      _command: string,
      _args: string[],
      _options: { cwd: string; env: NodeJS.ProcessEnv },
    ) => {
      await fs.mkdir(path.join(outputDir, "culture"), { recursive: true });
      await fs.writeFile(path.join(outputDir, "Example.dll"), "assembly");
      await fs.writeFile(path.join(outputDir, "culture", "Example.dll"), "culture");
      await fs.writeFile(path.join(outputDir, "dotnet.js"), "ignored");
      await fs.writeFile(path.join(outputDir, "runtime.wasm"), "ignored");
    });

    await publishDotnetWeb({
      configuration: "ExportRelease",
      nugetPackagesDir: path.join(projectDir, "nuget-packages"),
      outputDir,
      projectFile,
      runDotnet,
    });

    expect(runDotnet.mock.calls[0]?.[1]).toEqual(expect.arrayContaining([
      "publish",
      projectFile,
      "browser-wasm",
      "-p:GodotTargetPlatform=web",
    ]));
    const manifest = await fs.readFile(path.join(outputDir, ".dotnet-publish-manifest"), "utf8");
    expect(manifest).toContain("Example.dll\t");
    expect(manifest).toContain("culture/Example.dll\t");
    expect(manifest).not.toContain("dotnet.js");
    expect(manifest).not.toContain("runtime.wasm");
  });

  it("packs, assembles, and patches the browser export", async () => {
    const directory = await tempDir();
    const templateDir = path.join(directory, "template");
    const packPath = path.join(directory, "project.pck");
    const outputPath = path.join(directory, "export", "index.html");
    await fs.mkdir(templateDir);
    await Promise.all([
      fs.writeFile(path.join(templateDir, "godot.js"), "DOTNET.setup({});;\nengine\n"),
      fs.writeFile(path.join(templateDir, "godot.wasm"), "wasm"),
      fs.writeFile(path.join(templateDir, "godot.audio.worklet.js"), "audio"),
      fs.writeFile(path.join(templateDir, "godot.audio.position.worklet.js"), "position"),
      fs.writeFile(
        path.join(templateDir, "godot.html"),
        "<title>$GODOT_PROJECT_NAME</title><script src=\"$GODOT_URL\"></script>" +
        "<script>const c=$GODOT_CONFIG;const t=$GODOT_THREADS_ENABLED;</script>" +
        "$GODOT_HEAD_INCLUDE $GODOT_SPLASH_COLOR $GODOT_SPLASH_CLASSES $GODOT_SPLASH",
      ),
    ]);
    const runGodot = vi.fn(async (
      _command: string,
      _args: string[],
      _cwd: string,
    ) => fs.writeFile(packPath, "pack"));

    await exportDotnetWebPack({
      godotArgs: [],
      godotCommand: "godot-mono",
      outputPath: packPath,
      preset: "Web",
      projectDir: directory,
      publishDir: path.join(directory, "publish"),
      runGodot,
    });
    await assembleDotnetWebExport({
      extractArchive: async (_file, output) => fs.cp(templateDir, output, { recursive: true }),
      outputPath,
      packPath,
      projectName: "A & B",
      templatePath: "fixture.zip",
    });
    await patchDotnetWebExport(outputPath);

    expect(runGodot.mock.calls[0]?.[1]).toEqual(expect.arrayContaining([
      "--export-pack",
      "Web",
      `--kirie-dotnet-web-publish=${path.join(directory, "publish")}`,
    ]));
    await expect(fs.readFile(outputPath, "utf8")).resolves.toContain("<title>A &amp; B</title>");
    await expect(fs.readFile(path.join(directory, "export", "index.js"), "utf8"))
      .resolves
      .toBe("engine\n");
    await expect(fs.readFile(path.join(directory, "export", "index.pck"), "utf8"))
      .resolves
      .toBe("pack");
  });
});

async function tempDir(): Promise<string> {
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), "kirie-dotnet-web-test-"));
  tempDirs.push(directory);
  return directory;
}

function testRelease(): DotnetWebRelease {
  return {
    asset: {
      archive: "templates.zip",
      sha256: "a".repeat(64),
      url: "https://example.com/templates.zip",
    },
    draftCommit: "draft-commit",
    godotCommit: "godot-commit",
    godotVersion: "4.7.2.stable.mono",
    tag: "preview-test",
    targetFramework: "net10.0",
  };
}

async function writeToolchain(directory: string, release: DotnetWebRelease): Promise<void> {
  await fs.mkdir(directory, { recursive: true });
  const files: Record<string, { sha256: string; size: number }> = {};
  for (const filename of payloadFiles) {
    const content = Buffer.from(`fixture:${filename}`);
    await fs.writeFile(path.join(directory, filename), content);
    files[filename] = {
      sha256: createHash("sha256").update(content).digest("hex"),
      size: content.length,
    };
  }
  await fs.writeFile(path.join(directory, "manifest.json"), JSON.stringify({
    draftCommit: release.draftCommit,
    files,
    godotCommit: release.godotCommit,
    godotVersion: release.godotVersion,
    release: release.tag,
    schemaVersion: 1,
    targetFramework: release.targetFramework,
  }));
}
